CREATE OR REPLACE FUNCTION public.fn_tournament_club_for_user(p_user_id uuid, p_tournament_id uuid, p_preferred_club uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_union uuid;
  v_t_club uuid;
  v_club uuid;
  v_is_horse boolean := false;
  v_n int;
  v_idx int;
  v_paying text;
BEGIN
  SELECT t.union_id, t.club_id INTO v_union, v_t_club
    FROM public.tournaments t WHERE t.id = p_tournament_id;

  IF v_union IS NULL THEN
    RETURN v_t_club;                       -- standalone club tournament
  END IF;

  /* THE WALLET THAT CAN PAY IS THE WALLET THAT PAYS (2026-10-12). */
  IF p_preferred_club IS NULL THEN
    v_paying := NULLIF(current_setting('app.ca_entry_paying_club', true), '');
    IF v_paying IS NOT NULL
       AND split_part(v_paying, ':', 1) = p_tournament_id::text
       AND split_part(v_paying, ':', 2) = p_user_id::text THEN
      RETURN split_part(v_paying, ':', 3)::uuid;
    END IF;
  END IF;

  /* THE HOST CLUB IS IN ITS OWN UNION (2026-09-10). */
  IF p_preferred_club IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.club_members m
        WHERE m.user_id = p_user_id
          AND m.club_id = p_preferred_club
          AND m.status IN ('active', 'approved')
          AND (
            m.club_id = v_t_club
            OR EXISTS (
              SELECT 1 FROM public.union_clubs uc
               WHERE uc.club_id = m.club_id
                 AND uc.union_id = v_union
            )
          )
     )
  THEN
    RETURN p_preferred_club;
  END IF;

  /* AN ENTRY'S LATER MONEY USES THE WALLET THE ENTRY CAME FROM (2026-10-12). */
  SELECT tp.club_id INTO v_club
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id
     AND tp.user_id = p_user_id
     AND tp.club_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.club_members m
        WHERE m.user_id = p_user_id
          AND m.club_id = tp.club_id
          AND m.status IN ('active', 'approved')
     )
   LIMIT 1;
  IF v_club IS NOT NULL THEN
    RETURN v_club;
  END IF;

  SELECT COALESCE(p.is_horse, false) INTO v_is_horse
    FROM public.profiles p
   WHERE p.id = p_user_id;

  IF v_is_horse THEN
    SELECT count(*) INTO v_n
      FROM public.club_members m
      JOIN public.union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
     WHERE m.user_id = p_user_id AND m.status IN ('active', 'approved');
    IF v_n > 1 THEN
      v_idx := (abs(hashtextextended(p_user_id::text, 0)) % v_n)::int;
      SELECT m.club_id INTO v_club
        FROM public.club_members m
        JOIN public.union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
       WHERE m.user_id = p_user_id AND m.status IN ('active', 'approved')
       ORDER BY m.club_id OFFSET v_idx LIMIT 1;
      IF v_club IS NOT NULL THEN RETURN v_club; END IF;
    END IF;
  END IF;

  -- Real players: prefer a union member club with positive chip balance, then oldest membership.
  SELECT m.club_id INTO v_club
    FROM public.club_members m
    JOIN public.union_clubs uc ON uc.club_id = m.club_id AND uc.union_id = v_union
   WHERE m.user_id = p_user_id AND m.status IN ('active', 'approved')
   ORDER BY (COALESCE(m.chip_balance, 0) > 0) DESC,
            COALESCE(m.chip_balance, 0) DESC,
            m.joined_at ASC NULLS LAST,
            m.club_id
   LIMIT 1;

  RETURN v_club;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_tournament_entry_cap_reached(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cap      integer;
  v_counter  integer;
  v_entries  integer;
BEGIN
  PERFORM public.fn_ca_lock_mtt_admission_contract();
  SELECT t.max_players, COALESCE(t.current_players, 0)
    INTO v_cap, v_counter
    FROM public.tournaments t
   WHERE t.id = p_tournament_id;

  IF NOT FOUND OR public.fn_ca_tournament_is_unlimited(p_tournament_id)
     OR v_cap IS NULL OR v_cap <= 0 THEN
    RETURN false;                      -- uncapped: this function never refuses
  END IF;

  SELECT count(*) INTO v_entries
    FROM public.tournament_players tp
   WHERE tp.tournament_id = p_tournament_id;

  /* GREATEST, never the entry count alone: this can only ever be stricter than
     the counter test it replaces, never looser. */
  RETURN GREATEST(v_counter, COALESCE(v_entries, 0)) >= v_cap;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_tournament_is_unlimited(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
 v_abi:=public.fn_ca_lock_mtt_admission_contract();
 IF v_abi='legacy-capacity-v1' THEN RETURN false; END IF;
 RETURN public.fn_ca_tournament_recorded_format(p_tournament_id) IN ('mtt-v1','mtt-v2');
END $function$
